# Player lifecycle diagnostics (custom build). Logging only: no retry, no engine switch,
# no player re-creation. Anchors live in player-diagnostics.patch.json (generated by
# player-diagnostics.gen.py); every anchor must occur exactly once or the build stops.
$ErrorActionPreference = 'Stop'
$source = $PSScriptRoot

Copy-Item "$source/PlayerDiagnostics.cs" 'src/ui/Logic/VideoPlayers/PlayerDiagnostics.cs' -Force
Copy-Item "$source/PlayerDiagnosticsTests.cs" 'tests/UI/Logic/PlayerDiagnosticsTests.cs' -Force

$patch = Get-Content "$source/player-diagnostics.patch.json" -Raw -Encoding utf8 | ConvertFrom-Json
$files = @{}
foreach ($edit in $patch.edits) {
    if (-not $files.ContainsKey($edit.file)) {
        $files[$edit.file] = (Get-Content $edit.file -Raw -Encoding utf8).Replace("`r`n", "`n")
    }
    $text = $files[$edit.file]
    $count = ([regex]::Matches($text, [regex]::Escape($edit.anchor))).Count
    if ($count -ne 1) { throw "Player diagnostics anchor found $count times in $($edit.file): $($edit.anchor.Split("`n")[0].Trim())" }
    $replacement = switch ($edit.mode) {
        'after'   { $edit.anchor + $edit.text }
        'before'  { $edit.text + $edit.anchor }
        'replace' { $edit.text }
        default   { throw "Unknown edit mode $($edit.mode)" }
    }
    $index = $text.IndexOf($edit.anchor, [StringComparison]::Ordinal)
    $files[$edit.file] = $text.Substring(0, $index) + $replacement + $text.Substring($index + $edit.anchor.Length)
}
foreach ($file in $files.Keys) {
    Set-Content $file $files[$file] -Encoding utf8 -NoNewline
}
Write-Host "Player diagnostics applied: $($patch.edits.Count) edits in $($files.Count) files."

